1	#!/usr/bin/env node
2	/**
3	 * Differential harness: run the reference executable and the Node port with
4	 * identical argv, then compare stdout, exit status and (normalised) stderr.
5	 *
6	 * Usage: node diff.mjs <cases.jsonl> [--cwd <dir>] [--jobs N]
7	 *
8	 * Cases are JSON lines: {"name": "...", "args": [...], "env": {...}}.
9	 * An arg may be {"raw": "<bash $'...' body>"} for byte sequences a JS string
10	 * cannot carry.
11	 *
12	 * Exit status 0 = every case matched.
13	 */
14	
15	import { spawn } from 'node:child_process';
16	import { chmodSync, copyFileSync, mkdirSync, readFileSync } from 'node:fs';
17	import { dirname } from 'node:path';
18	
19	/**
20	 * The reference is invoked through a copy named `test13.mjs` so that argparse's
21	 * `prog` (basename of argv[0]) is identical on both sides — that turns the one
22	 * inherent divergence into an exact comparison of stdout AND stderr.
23	 * Pass --raw-reference to use the original name instead.
24	 */
25	const REFERENCE_COPY = '/tmp/refprog/test13.mjs';
26	const REFERENCE_ORIGINAL = '/workspace/dataset/test13_executable';
27	const PORT = ['node', '/output/test13.mjs'];
28	
29	const argv = process.argv.slice(2);
30	const casesPath = argv[0];
31	const option = (name, fallback) => {
32	  const at = argv.indexOf(name);
33	  return at === -1 ? fallback : argv[at + 1];
34	};
35	const workingDirectory = option('--cwd', process.cwd());
36	const jobs = Number(option('--jobs', '16'));
37	const rawReference = argv.includes('--raw-reference');
38	
39	if (!rawReference) {
40	  mkdirSync(dirname(REFERENCE_COPY), { recursive: true });
41	  copyFileSync(REFERENCE_ORIGINAL, REFERENCE_COPY);
42	  chmodSync(REFERENCE_COPY, 0o755);
43	}
44	const REFERENCE = [rawReference ? REFERENCE_ORIGINAL : REFERENCE_COPY];
