46	/** Only the bootloader's pid can never match; everything else must. */
47	const normalise = (text) => {
48	  const withoutPid = text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-N:ERROR]');
49	  return rawReference
50	    ? withoutPid.replace(/test13_executable/g, '<prog>').replace(/test13\.mjs/g, '<prog>')
