56	/** Build a bash command that execs a program with possibly-raw byte args. */
57	function invocation(command, args) {
58	  const quoted = args.map((argument) =>
59	    typeof argument === 'object' && argument !== null && 'raw' in argument
60	      ? `$'${argument.raw}'`
61	      : shellQuote(String(argument)),
62	  );
63	  return `exec ${command.map(shellQuote).join(' ')} ${quoted.join(' ')}`;
