66	/** Run one program, collecting output as latin1 so bytes survive intact. */
67	function run(command, args, env) {
68	  return new Promise((resolve) => {
69	    const child = spawn('/bin/bash', ['-c', invocation(command, args)], {
70	      cwd: workingDirectory,
71	      env: { ...process.env, ...env },
72	    });
73	    const out = [];
74	    const err = [];
75	    child.stdout.on('data', (chunk) => out.push(chunk));
76	    child.stderr.on('data', (chunk) => err.push(chunk));
77	    child.on('close', (status) =>
78	      resolve({
79	        status,
80	        stdout: Buffer.concat(out).toString('latin1'),
81	        stderr: Buffer.concat(err).toString('latin1'),
82	      }),
